418 if (C_d) cudaFree(C_d);
419 if (work) cudaFree(work);
420 if (workJit) cudaFree(workJit);
421
422 printf("Successful completion\n");
423 return 0;
424}

Migrating from CAL to NCCL#
This guide describes how to migrate cuSOLVERMp applications from CAL (Communication Abstraction Layer) to NCCL (NVIDIA Collective Communications Library).
Overview of Changes#
The migration from CAL to NCCL involves several key changes in the initialization and synchronization patterns:
Simplified initialization - NCCL requires fewer setup steps.
Different communicator management - Direct NCCL communicator instead of CAL wrapper.
Change in grid and redistribution API calls - The type of the communicator parameter has been changed from
cal_comm_t
toncclComm_t
.Modified synchronization calls - Using CUDA streams instead of CAL-specific synchronization.
Key Differences#
Header Changes#
CAL Version:
#include <cal.h>
NCCL Version:
// NCCL headers are included automatically with cuSOLVERMp
Variable Declarations#
CAL Version:
cal_comm_t cal_comm = nullptr;
NCCL Version:
ncclUniqueId id;
ncclComm_t nccl_comm;
Initialization Process#
The CAL initialization process involves creating a communicator with explicit parameters:
cal_comm_t cal_comm = nullptr;
#ifdef USE_CAL_MPI
CAL_CHECK(cal_comm_create_mpi(MPI_COMM_WORLD, rank, nranks, local_device, &cal_comm));
#else
cal_comm_create_params_t params;
params.allgather = allgather;
params.req_test = request_test;
params.req_free = request_free;
params.data = (void*)(MPI_COMM_WORLD);
params.rank = rank;
params.nranks = nranks;
params.local_device = local_device;
CAL_CHECK(cal_comm_create(params, &cal_comm));
#endif
The NCCL initialization is more streamlined:
ncclUniqueId id;
if (rank == 0)
{
NCCL_CHECK(ncclGetUniqueId(&id));
}
MPI_CHECK(MPI_Bcast(&id, sizeof(id), MPI_BYTE, 0, MPI_COMM_WORLD));
ncclComm_t nccl_comm;
NCCL_CHECK(ncclCommInitRank(&nccl_comm, nranks, id, rank));
Other API changes#
cusolverMpCreateDeviceGrid accepts the communicator as one of its parameters. The type has been changed from cal_comm_t
to ncclComm_t
.
CAL Version:
CUSOLVER_CHECK(cusolverMpCreateDeviceGrid(handle, &grid, cal_comm, nprow, npcol, CUSOLVERMP_GRID_MAPPING_COL_MAJOR));
NCCL Version:
CUSOLVER_CHECK(cusolverMpCreateDeviceGrid(handle, &grid, nccl_comm, nprow, npcol, CUSOLVERMP_GRID_MAPPING_COL_MAJOR));
Synchronization Changes#
CAL uses specialized synchronization functions:
CAL_CHECK(cal_stream_sync(cal_comm, stream));
CAL_CHECK(cal_comm_barrier(cal_comm, stream));
NCCL relies on standard CUDA stream synchronization:
CUDA_CHECK(cudaStreamSynchronize(stream));
Cleanup Changes#
CAL:
CAL_CHECK(cal_comm_barrier(cal_comm, stream));
CAL_CHECK(cal_comm_destroy(cal_comm));
NCCL:
NCCL_CHECK(ncclCommDestroy(nccl_comm));
Migration Checklist#
Remove CAL includes - Remove CAL-related includes such as
#include <cal.h>
and#include <cal_mpi.h>
.Update variable declarations - Replace
cal_comm_t
withncclComm_t
andncclUniqueId
.Modify initialization - Replace CAL communicator creation with NCCL initialization pattern.
Update grid and redistribution API calls - Pass NCCL communicator instead of CAL communicator.
Change synchronization - Replace CAL-specific synchronization calls with
cudaStreamSynchronize
.Update cleanup - Use NCCL finalization and destruction functions.

CAL Initialization (Legacy)#
Warning
CAL is deprecated as of cuSOLVERMp v0.7.0. Please use NCCL Initialization instead.
Communication Abstraction Library (CAL) is a helper module for the cuSOLVERMp library that allows it to efficiently perform communications between different GPUs. The cuSOLVERMp grid creation API accepts cal_comm_t
communicator object and requires it to be created prior to any cuSOLVERMp call.
As of now, CAL supports only the use-case where each participating process uses single GPU and each participating GPU can only be used by a single process.
Communication Abstraction Library#
Communications Description#
In order to initialize communicator handle cal_comm_t
you would need to follow bootstrapping process - see respective cal_comm_create() function or example how to create communicator handle with MPI.
The main communication backend used by cuSOLVERMp is modular OpenUCC library. OpenUCC transports modules (such as OpenUCX, NCCL, and others) that will be used at runtime and their configuration can be controlled in various ways (i.e. environment variables that affects NCCL: https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html, environment variables that affects OpenUCX: https://openucx.readthedocs.io/en/master/faq.html) - refer to your platform provider if there are known optimized settings for these dependencies. Otherwise cuSOLVERMp and UCC will use default values.
Based on the nature of underlying communications there are few restrictions to keep in mind when using cuSOLVERMp:
Only one cuSOLVERMp routine can be in the fly at any point of time. It is possible, however, to create and keep multiple communications/cuSOLVERMp handles, but it’s a user’s responsibility to ensure that execution of cuSOLVERMp routines do not overlap.
If you are using NCCL communication library, NCCL collective calls should not overlap with cuSOLVERMp calls to avoid possible deadlocks.
Configuring Communications Submodule#
There are few environment variables that can change communication module behavior.
Variable |
Description |
|---|---|
CAL_LOG_LEVEL |
Verbosity level of communication module, where |
UCC_CONFIG_FILE |
Custom config file for UCC library. It can control underlying transports and collective parameters. Refer to UCC documentation for details on configuration syntax. Default - built-in cuSOLVERMp UCC configuration. |
By default cuSOLVERMp will use UCC configuration file provided in the release package: share/ucc.conf
, library will load it using path relative to the cuSOLVERMp shared object location.
Creating Communicator Handle with MPI#
If your application uses Message Passing Interface (MPI) for distributed communications, it can be used to bootstrap Communication Abstraction Library communicator:
#include "cal.h"
#include "cusolverMp.h"
#include "mpi.h"
calError_t allgather(void* src_buf, void* recv_buf, size_t size, void* data, void** request)
{
MPI_Request req;
int err = MPI_Iallgather(src_buf, size, MPI_BYTE, recv_buf, size, MPI_BYTE, (MPI_Comm)data, &req);
if (err != MPI_SUCCESS)
{
return CAL_ERROR;
}
*request = (void*)req;
return CAL_OK;
}
calError_t request_test(void* request)
{
MPI_Request req = (MPI_Request)request;
int completed;
int err = MPI_Test(&req, &completed, MPI_STATUS_IGNORE);
if (err != MPI_SUCCESS)
{
return CAL_ERROR;
}
return completed ? CAL_OK : CAL_ERROR_INPROGRESS;
}
calError_t request_free(void* request)
{
return CAL_OK;
}
calError_t cal_comm_create_mpi(MPI_Comm mpi_comm, int rank, int nranks, int local_device, cal_comm_t* comm)
{
cal_comm_create_params_t params;
params.allgather = allgather;
params.req_test = request_test;
params.req_free = request_free;
params.data = (void*)mpi_comm;
params.rank = rank;
params.nranks = nranks;
params.local_device = local_device;
return cal_comm_create(params, comm);
}
void main()
{
// Initialize MPI
MPI_Init(...);
int rank, size;
MPI_Comm mpi_comm = MPI_COMM_WORLD;
MPI_Comm_rank(mpi_comm, &rank);
MPI_Comm_size(mpi_comm, &size);
cal_comm_t cal_comm;
// creating communicator handle with MPI communicator
cal_comm_create_mpi(mpi_comm, rank, size, &cal_comm);
// using cuSOLVERMp with cal_comm handle
cusolverMpCreateDeviceGrid(..., cal_comm, ...);
// destroying communicator handle
cal_comm_destroy(cal_comm);
MPI_Finalize();
}
For convenience, these helper functions with MPI are also provided in source form in the release package in src
folder.
